var characters = booktxt.split('');
var classMap = {};
for (let i = 0; i < characters.length; i++) {
    var className = `n_${i + 1}`; 
    classMap[className] = characters[i];
}


function replaceEmContent(html) {
    var regex = /<em\s+class="[^"]*\b(n_\d+)\b[^"]*"[^>]*>([^<]*)<\/em>/g;

    return html.replace(regex, (match, className) => {

        return classMap[className] || match;
    });
}

var originalHTML = result

var processedHTML = replaceEmContent(originalHTML);
processedHTML;</js>

